from itertools import combinations

from minimal_pairs import LEXICON, drill, find_pairs, group_by_contrast


def brute_force_count(lexicon):
    """Independent recount of minimal pairs, no shared logic with library."""
    words = list(lexicon)
    count = 0
    for i in range(len(words)):
        for j in range(i + 1, len(words)):
            a, b = lexicon[words[i]], lexicon[words[j]]
            if len(a) != len(b):
                continue
            if sum(1 for x, y in zip(a, b) if x != y) == 1:
                count += 1
    return count


def test_vowel_length_bucket():
    pairs = find_pairs(LEXICON)
    buckets = group_by_contrast(pairs)
    members = {(w1, w2) for w1, w2, _, _ in buckets["ɪ/iː"]}
    assert ("ship", "sheep") in members
    assert ("chip", "cheap") in members
    assert len(members) >= 4  # ship/sheep, chip/cheap, slip/sleep, bit/beat, sit/seat


def test_affricate_contrast():
    buckets = group_by_contrast(find_pairs(LEXICON))
    affricate = {
        (min(w1, w2), max(w1, w2))
        for w1, w2, _, _ in buckets["ʃ/tʃ"]
    }
    assert ("chip", "ship") in affricate
    assert ("cheap", "sheep") in affricate


def test_final_position_pair():
    found = [(w1, w2, pos) for w1, w2, pos, _ in find_pairs(LEXICON)]
    assert ("bad", "bat", 2) in found


def test_different_lengths_never_pair():
    pairs = set()
    for w1, w2, *_ in find_pairs(LEXICON):
        pairs.add(frozenset((w1, w2)))
    for wa, wb in combinations(LEXICON, 2):
        if len(LEXICON[wa]) != len(LEXICON[wb]):
            assert frozenset((wa, wb)) not in pairs


def test_total_matches_brute_force():
    assert len(find_pairs(LEXICON)) == brute_force_count(LEXICON)


def test_drill_deterministic():
    first = drill("ɪ/iː", 3, seed=42)
    again = drill("ɪ/iː", 3, seed=42)
    other = drill("ɪ/iː", 3, seed=7)
    assert first == again
    assert len(first) == 3
    assert all(pair in group_by_contrast(find_pairs(LEXICON))["ɪ/iː"] for pair in first)

