# Canonical phoneme ordering used to name unordered contrasts deterministically
# (short vowel before its long counterpart, fricative before affricate, etc.).
_PHONEME_RANK = {
    ph: i
    for i, ph in enumerate(
        [
            "p", "b", "t", "d", "k", "ɡ", "f", "v", "θ", "ð",
            "s", "z", "ʃ", "ʒ", "tʃ", "dʒ", "m", "n", "ŋ", "l", "r",
            "w", "j", "ɪ", "iː", "ɛ", "æ", "ʌ", "ɒ", "ʊ", "uː",
            "ɔː", "ɑː", "ə", "ɜː",
        ]
    )
}


def _contrast_key(contrast):
    a, b = contrast.split("/")
    rank = _PHONEME_RANK.get
    return "/".join(sorted((a, b), key=lambda p: (rank(p), p)))


